import { normalizeHelpManifest } from "../../src/features/help/help-manifest.mjs";

const HELP_MANIFEST_HEADING = "Help manifest";
const MISSING_MANIFEST_ERROR =
  "This issue needs the complete Help manifest generated by Tavernary.";

function readableValue(value = "") {
  const normalized = String(value).trim();
  return /^_No response_$/iu.test(normalized) ? "" : normalized;
}

function collectManifestHeading(body = "") {
  let value;
  let duplicate = false;
  for (const section of String(body).split(/^### /mu).slice(1)) {
    const [heading, ...content] = section.split(/\r?\n/u);
    if (heading.trim() !== HELP_MANIFEST_HEADING) continue;
    if (value !== undefined) {
      duplicate = true;
      continue;
    }
    value = readableValue(content.join("\n"));
  }
  return { value: value ?? "", duplicate };
}

function renderedJson(value) {
  const fenced = value.match(/^```(?:json)?\s*\r?\n([\s\S]*?)\r?\n```$/iu);
  return fenced?.[1] ?? value;
}

function parseManifest(value) {
  let candidate;
  try {
    candidate = JSON.parse(renderedJson(value));
  } catch {
    return {
      valid: false,
      errors: ["Help manifest is not valid JSON."],
    };
  }
  const validation = normalizeHelpManifest(candidate);
  return validation.valid
    ? { valid: true, source: "manifest", manifest: validation.manifest }
    : { valid: false, errors: validation.errors };
}

export function parseHelpIssue(body = "") {
  const { value, duplicate } = collectManifestHeading(body);
  if (duplicate) {
    return {
      valid: false,
      errors: ["Help issue contains a duplicate recognized form heading."],
    };
  }
  if (!value) {
    return {
      valid: false,
      errors: [MISSING_MANIFEST_ERROR],
    };
  }
  return parseManifest(value);
}
